const CAMERA_STATUS_ROUTES=["/api/unit-camera-status","/api/unit-camera-status/edit"];
const CAMERA_BODY_LIMIT=65536;
function cameraRepeated(pathname){
  const lower=String(pathname||"").toLowerCase();
  const slugs=["cos-unit-camera-status","cos-operations-pages","cos-operations-bridge","cos-fleet-board-producer"];
  let total=0;
  for(const slug of slugs){
    const count=(lower.match(new RegExp("/"+slug+"(?=\\/|$)","g"))||[]).length;
    if(count>1) return true;
    total+=count;
  }
  return total>1;
}
function cameraSeenPath(url){
  let rewritten;
  try{ rewritten=new URL(handlerUrl(url)).pathname; }
  catch{ return null; }
  const original=new URL(url).pathname;
  if(cameraRepeated(original)||cameraRepeated(rewritten)) return null;
  const stripped=rewritten.toLowerCase().replace(/^.*\/cos-(?:unit-camera-status|operations-(?:pages|bridge)|fleet-board-producer)(?=\/|$)/,"").replace(/\/$/,"");
  if(stripped!==""&&!CAMERA_STATUS_ROUTES.includes(stripped)) return null;
  return stripped;
}
function cameraNotFound(){
  return new Response(JSON.stringify({error:"COS endpoint not found."}),{status:404,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}});
}
async function readCameraBody(request){
  const reader=request.body?.getReader();
  if(!reader)return "";
  const chunks=[];
  let size=0;
  try{
    while(true){
      const next=await reader.read();
      if(next.done)break;
      size+=next.value.byteLength;
      if(size>CAMERA_BODY_LIMIT){
        await reader.cancel();
        const error=new Error("too-big");
        error.tooBig=true;
        throw error;
      }
      chunks.push(next.value);
    }
  }finally{try{reader.releaseLock();}catch{}}
  const bytes=new Uint8Array(size);
  let offset=0;
  for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
  return new TextDecoder("utf-8",{fatal:false}).decode(bytes);
}
